func (bc *bc) Exec(code string) error {
	bc.stdin.Write([]byte(code))
	bc.stdin.Write(inputSuffix)
	for {
		b, err := readByte(bc.stdout)
		if err != nil {
			return err
		}
		if b == 0x04 {
			break
		}
		os.Stdout.Write([]byte{b})
	}
	return nil
}

