		OnFilter: func(w tk.ComboBox, p string) {
			items := filterLastcmdItems(entries, p)
			if len(items.entries) == 1 {
				accept(items.entries[0].content)
			} else {
				w.ListBox().Reset(items, 0)
			}
		},
	})
	return w, nil
}

